import json, sys

path = sys.argv[1]
n = int(sys.argv[2]) if len(sys.argv) > 2 else 20
rows = []
for line in open(path):
    try:
        rows.append(json.loads(line))
    except Exception:
        pass

for r in rows[-n:]:
    t = r.get("type")
    m = r.get("message", {}) or {}
    c = m.get("content")
    parts = []
    if isinstance(c, str):
        parts.append(("text", c))
    elif isinstance(c, list):
        for b in c:
            if not isinstance(b, dict):
                continue
            bt = b.get("type")
            if bt == "text":
                parts.append(("text", b.get("text", "")))
            elif bt == "thinking":
                parts.append(("think", b.get("thinking", "")[:300]))
            elif bt == "tool_use":
                parts.append(("tool:" + str(b.get("name")), json.dumps(b.get("input", {}))[:800]))
            elif bt == "tool_result":
                rc = b.get("content")
                s = rc if isinstance(rc, str) else json.dumps(rc)
                parts.append(("result", s[:500]))
    print("=====", t, r.get("timestamp"))
    for k, v in parts:
        print("  [%s] %s" % (k, v[:2000]))
